{"path": "/tmp/sv-65bcd6884c08437b9cf9fa2fe3ca61dc/Components/Pages/Board/KanbanColumn.razor", "file_text": "@using sv_65bcd6884c08437b9cf9fa2fe3ca61dc.Services

<div class="kanban-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="column-count">@Tasks.Count</span>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      OnMoveLeft="() => HandleMoveLeft(task)"
                      OnMoveRight="() => HandleMoveRight(task)" />
        }
    </div>

    <div class="column-footer">
        @if (showForm)
        {
            <AddTaskForm OnSave="HandleSave" OnCancel="() => showForm = false" />
        }
        else
        {
            <button class="btn-add-task" @onclick="() => showForm = true">Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = string.Empty;
    [Parameter, EditorRequired] public string Status { get; set; } = string.Empty;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<(int TaskId, string NewStatus)> OnMoveTask { get; set; }
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate, string Status)> OnAddTask { get; set; }

    private bool showForm;

    private async Task HandleMoveLeft(TaskItem task)
    {
        var newStatus = Status switch
        {
            "In Progress" => "To Do",
            "Done" => "In Progress",
            _ => Status
        };
        await OnMoveTask.InvokeAsync((task.Id, newStatus));
    }

    private async Task HandleMoveRight(TaskItem task)
    {
        var newStatus = Status switch
        {
            "To Do" => "In Progress",
            "In Progress" => "Done",
            _ => Status
        };
        await OnMoveTask.InvokeAsync((task.Id, newStatus));
    }

    private async Task HandleSave((string Title, string Assignee, string Priority, DateTime DueDate) formData)
    {
        await OnAddTask.InvokeAsync((formData.Title, formData.Assignee, formData.Priority, formData.DueDate, Status));
        showForm = false;
    }
}
"}

